package com.notesshared.servlet;
import com.notesshared.dao.*;import com.notesshared.util.WebUtil;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet({"/admin/dashboard","/admin/courses","/admin/course/create","/admin/pending"}) public class AdminServlet extends HttpServlet{private final CourseDao courses=new CourseDao();private final UserDao users=new UserDao();
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{int cid=(int)r.getSession().getAttribute("collegeId");try{switch(r.getServletPath()){case "/admin/dashboard"->{r.setAttribute("courses",courses.findByCollege(cid));r.setAttribute("pending",users.findPendingByCollege(cid));r.getRequestDispatcher("/WEB-INF/admin/dashboard.jsp").forward(r,s);}case "/admin/courses"->{r.setAttribute("courses",courses.findByCollege(cid));r.getRequestDispatcher("/WEB-INF/admin/courses.jsp").forward(r,s);}case "/admin/course/create"->r.getRequestDispatcher("/WEB-INF/admin/course-create.jsp").forward(r,s);default->{r.setAttribute("pending",users.findPendingByCollege(cid));r.getRequestDispatcher("/WEB-INF/admin/pending.jsp").forward(r,s);}}}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{int cid=(int)r.getSession().getAttribute("collegeId");try{String code=r.getParameter("code"),name=r.getParameter("name");int sc=Integer.parseInt(r.getParameter("semesterCount"));if(code==null||code.isBlank()||name==null||name.isBlank()||sc<1||sc>20)throw new IllegalArgumentException("Course code/name and a semester count from 1 to 20 are required.");List<List<String>> all=new ArrayList<>();for(int sem=1;sem<=sc;sem++){int n=Integer.parseInt(r.getParameter("subjectCount_"+sem));if(n<1||n>30)throw new IllegalArgumentException("Each semester needs 1 to 30 subjects.");List<String> subs=new ArrayList<>();for(int i=1;i<=n;i++){String v=r.getParameter("subject_"+sem+"_"+i);if(v==null||v.isBlank())throw new IllegalArgumentException("Every subject name is required.");subs.add(v.trim());}all.add(subs);}courses.createWithStructure(cid,code.trim().toUpperCase(),name.trim(),sc,all);WebUtil.setFlash(r.getSession(),"success","Course and semester/subject structure created.");s.sendRedirect(r.getContextPath()+"/admin/courses");}catch(Exception e){r.setAttribute("error",e.getMessage());r.getRequestDispatcher("/WEB-INF/admin/course-create.jsp").forward(r,s);}}
}
